fn in_set_a(c: char) -> bool {
    matches!(
        c,
        'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M' | 'N' | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z'
    )
}

fn in_set_b(c: char) -> bool {
    matches!(c, 'B' | 'C' | 'D' | 'G' | 'J' | 'O' | 'P' | 'Q' | 'R' | 'S' | 'U')
}

fn solve(word: Vec<char>) -> (Vec<char>) {
    if word.is_empty() {
        // Not expected per constraints, but keep behavior defined.
        return ("NO".chars().collect(),);
    }

    let first = word[0];
    let first_in_a = in_set_a(first);
    let first_in_b = in_set_b(first);

    // If somehow not in either set, reject (should not happen for uppercase A-Z here).
    if !first_in_a && !first_in_b {
        return ("NO".chars().collect(),);
    }

    for &c in &word {
        let ok = if first_in_a { in_set_a(c) } else { in_set_b(c) };
        if !ok {
            return ("NO".chars().collect(),);
        }
    }

    ("YES".chars().collect(),)
}